// Package bootstrap provides the embedded bootstrap archive for zqk system init.
// The archive is built by the build process (make bootstrap-archive) from .zqk/specs.
// REQ-9009: Build process creates bootstrap archive; REQ-9011: manifest provides traceability.
package bootstrap

import (
	"embed"
	"strings"
)

const emptyValue = ""

const embeddedManifestPath = "archive/manifest.txt"

// Archive and manifest are generated by scripts/build-bootstrap-archive.sh (make bootstrap-archive).
//
//go:embed archive/bootstrap.tar.gz archive/manifest.txt
var archiveFS embed.FS

// ManifestPaths returns the list of file paths bundled in the bootstrap archive (REQ-9011 traceability).
// Returns nil if the manifest cannot be read (e.g. dev build without archive).
func ManifestPaths() []string {
	data, err := archiveFS.ReadFile(embeddedManifestPath)
	if err != nil {
		return nil
	}
	lines := strings.Split(strings.TrimSpace(string(data)), "\n")
	out := make([]string, 0, len(lines))
	for _, line := range lines {
		if s := strings.TrimSpace(line); s != emptyValue {
			out = append(out, s)
		}
	}
	return out
}
